INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Entspricht /30 der Dezimalmaske 255.255.255.252?', 2, '[{"text": "Ja", "correct": true, "because": "30 Bits = 252 im letzten Oktett"}, {"text": "Nein", "correct": false, "because": "Korrekte Umrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dezimalmaske hat /22?', 3, '[{"text": "255.255.252.0", "correct": true, "because": "22 Bits = 252 im 3. Oktett"}, {"text": "255.255.255.0", "correct": false, "because": "24 Bits"}, {"text": "255.255.240.0", "correct": false, "because": "20 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /16 ist 255.255.0.0. b) /24 ist 255.255.255.240.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/24 ist 255.255.255.0"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was übersehe ich bei der Umrechnung von /18 zu einer Dezimalmaske?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Kern der Berechnung"}, {"text": "Oktettstruktur", "correct": false, "because": "Ergebnisformat"}, {"text": "Softwareversion", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /25 gleich 255.255.255.128 ist?', 2, '[{"text": "Ja", "correct": true, "because": "25 Bits = 128 im 4. Oktett"}, {"text": "Nein", "correct": false, "because": "Korrekte Umrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske ergibt sich aus /27?', 3, '[{"text": "255.255.255.224", "correct": true, "because": "27 Bits = 224 im 4. Oktett"}, {"text": "255.255.255.192", "correct": false, "because": "26 Bits"}, {"text": "255.255.255.240", "correct": false, "because": "28 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche CIDR-Werte passen zu diesen Dezimalmasken?', 5, '[{"text": "/20 = 255.255.240.0", "correct": true, "because": "20 Bits"}, {"text": "/28 = 255.255.255.240", "correct": true, "because": "28 Bits"}, {"text": "/24 = 255.255.0.0", "correct": false, "because": "24 Bits = 255.255.255.0"}, {"text": "/16 = 255.255.255.0", "correct": false, "because": "16 Bits = 255.255.0.0"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /26 ist 255.255.255.192. b) /30 ist 255.255.255.0. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/30 ist 255.255.255.252"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was benötige ich nicht für die Umrechnung von /29?', 4, '[{"text": "Bitweise Zählung", "correct": false, "because": "Bestimmt Maske"}, {"text": "Oktettberechnung", "correct": false, "because": "Formatiert Ergebnis"}, {"text": "Netzwerkprotokoll", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist /8 gleich 255.0.0.0?', 2, '[{"text": "Ja", "correct": true, "because": "8 Bits = 255 im 1. Oktett"}, {"text": "Nein", "correct": false, "because": "Korrekte Umrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dezimalmaske hat /19?', 4, '[{"text": "255.255.224.0", "correct": true, "because": "19 Bits = 224 im 3. Oktett"}, {"text": "255.255.240.0", "correct": false, "because": "20 Bits"}, {"text": "255.255.192.0", "correct": false, "because": "18 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /32 keine gültige Dezimalmaske hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "255.255.255.255 ist gültig"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist entscheidend bei der Umrechnung von /23?', 3, '[{"text": "Bitanzahl pro Oktett", "correct": true, "because": "Bestimmt Dezimalwert"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufallswerte", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /14 ist 255.252.0.0. b) /26 ist 255.255.255.252.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/26 ist 255.255.255.192"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dezimalmasken passen zu diesen CIDR-Werten?', 5, '[{"text": "/17 = 255.255.128.0", "correct": true, "because": "17 Bits"}, {"text": "/31 = 255.255.255.254", "correct": true, "because": "31 Bits"}, {"text": "/25 = 255.255.255.192", "correct": false, "because": "25 Bits = 255.255.255.128"}, {"text": "/22 = 255.255.255.0", "correct": false, "because": "22 Bits = 255.255.252.0"}]'),
('00000000-0000-0000-0000-000000000000', 'Was spielt bei der Umrechnung von /21 keine Rolle?', 3, '[{"text": "Bitpositionen", "correct": false, "because": "Bestimmen Maske"}, {"text": "Oktettgrenzen", "correct": false, "because": "Strukturieren Ergebnis"}, {"text": "Farbcodierung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist /12 gleich 255.240.0.0?', 3, '[{"text": "Ja", "correct": true, "because": "12 Bits = 240 im 2. Oktett"}, {"text": "Nein", "correct": false, "because": "Korrekte Umrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /15 255.254.0.0 ergibt?', 2, '[{"text": "Ja", "correct": true, "because": "15 Bits = 254 im 2. Oktett"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske entspricht /13?', 4, '[{"text": "255.248.0.0", "correct": true, "because": "13 Bits = 248 im 2. Oktett"}, {"text": "255.252.0.0", "correct": false, "because": "14 Bits"}, {"text": "255.255.0.0", "correct": false, "because": "16 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche CIDR-Notation ergibt 255.255.255.248?', 3, '[{"text": "/29", "correct": true, "because": "29 Bits = 248 im 4. Oktett"}, {"text": "/28", "correct": false, "because": "16 im 4. Oktett"}, {"text": "/30", "correct": false, "because": "252 im 4. Oktett"}]');
